BEGIN;
DO $test$
DECLARE h uuid;parent uuid;child1 uuid;child2 uuid;outsider uuid;i uuid:=gen_random_uuid();r jsonb;n integer;
BEGIN
 SELECT household_id INTO STRICT h FROM bb_planner_private.routines WHERE routine_key='prepare_for_tomorrow_v1';
 SELECT user_id INTO STRICT parent FROM public.bb_planner_members WHERE household_id=h AND member_role='adult' ORDER BY user_id LIMIT 1;
 SELECT user_id INTO STRICT child1 FROM public.bb_planner_members WHERE household_id=h AND member_role='child' ORDER BY user_id LIMIT 1;
 SELECT user_id INTO STRICT child2 FROM public.bb_planner_members WHERE household_id=h AND member_role='child' AND user_id<>child1 LIMIT 1;
 SELECT user_id INTO STRICT outsider FROM public.bb_planner_members m WHERE NOT EXISTS(SELECT FROM public.bb_planner_members x WHERE x.household_id=h AND x.user_id=m.user_id) LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',child1::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.bb_grocery_write(h,i,NULL,'add','Rollback fictional oats','2 bags',NULL);
 IF r->>'created_by'<>child1::text OR (r->>'version')::int<>1 THEN RAISE EXCEPTION 'Creator/version';END IF;
 PERFORM public.bb_grocery_write(h,i,NULL,'add','Rollback fictional oats','2 bags',NULL);
 BEGIN PERFORM public.bb_grocery_write(h,gen_random_uuid(),NULL,'add',' ','',NULL);RAISE EXCEPTION 'Blank accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 r:=public.bb_grocery_write(h,i,1,'edit','Rollback revised oats','3 bags',NULL);
 IF (r->>'version')::int<>2 THEN RAISE EXCEPTION 'Own child edit';END IF;
 PERFORM set_config('request.jwt.claim.sub',child2::text,true);
 SELECT count(*) INTO n FROM public.bb_grocery_items WHERE id=i;IF n<>1 THEN RAISE EXCEPTION 'Sibling visibility';END IF;
 BEGIN PERFORM public.bb_grocery_write(h,i,2,'edit','Sibling rename','',NULL);RAISE EXCEPTION 'Sibling edit';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_grocery_write(h,i,2,'archive',NULL,NULL,NULL);RAISE EXCEPTION 'Child archive';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.bb_grocery_write(h,i,2,'pick',NULL,NULL,true);
 IF r->>'picked_by'<>child2::text OR NOT(r->>'is_picked')::boolean OR r->>'picked_at' IS NULL THEN RAISE EXCEPTION 'Pickup attribution';END IF;
 BEGIN PERFORM public.bb_grocery_write(h,i,2,'pick',NULL,NULL,false);RAISE EXCEPTION 'Stale pickup';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.bb_grocery_write(h,i,3,'pick',NULL,NULL,NULL);RAISE EXCEPTION 'Null pickup';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',parent::text,true);
 r:=public.bb_grocery_write(h,i,3,'pick',NULL,NULL,false);IF (r->>'is_picked')::boolean OR r->>'picked_by' IS NOT NULL THEN RAISE EXCEPTION 'Undo attribution';END IF;
 PERFORM public.bb_grocery_write(h,i,4,'edit','Parent corrected oats','1 bag',NULL);
 r:=public.bb_grocery_write(h,i,5,'archive',NULL,NULL,NULL);IF NOT(r->>'is_archived')::boolean THEN RAISE EXCEPTION 'Archive';END IF;
 BEGIN PERFORM public.bb_grocery_write(h,i,6,'pick',NULL,NULL,true);RAISE EXCEPTION 'Archived mutable';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
 BEGIN UPDATE public.bb_grocery_items SET title='Direct bypass' WHERE id=i;RAISE EXCEPTION 'Direct update';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.bb_grocery_items(id,household_id,created_by,title) VALUES(gen_random_uuid(),h,parent,'Direct bypass');RAISE EXCEPTION 'Direct insert';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);
 SELECT count(*) INTO n FROM public.bb_grocery_items WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Other household leak';END IF;
 BEGIN PERFORM public.bb_grocery_write(h,gen_random_uuid(),NULL,'add','Foreign attempt','',NULL);RAISE EXCEPTION 'Foreign create';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_grocery_write(h,i,6,'pick',NULL,NULL,true);RAISE EXCEPTION 'Foreign mutation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub','',true);
 BEGIN PERFORM public.bb_grocery_write(h,gen_random_uuid(),NULL,'add','No identity','',NULL);RAISE EXCEPTION 'Missing identity';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'SET LOCAL ROLE postgres';
 SELECT count(*) INTO n FROM bb_planner_private.grocery_changes WHERE item_id=i;IF n<>6 THEN RAISE EXCEPTION 'History count %',n;END IF;
 IF has_function_privilege('anon','public.bb_grocery_write(uuid,uuid,bigint,text,text,text,boolean)','EXECUTE') OR has_table_privilege('anon','public.bb_grocery_items','SELECT') OR has_table_privilege('authenticated','public.bb_grocery_items','DELETE') OR has_table_privilege('authenticated','bb_planner_private.grocery_changes','SELECT') OR pg_has_role('authenticated','bb_grocery_writer','MEMBER') THEN RAISE EXCEPTION 'ACL exposure';END IF;
 RAISE NOTICE 'PASS grocery roles, visibility, retries, own edit, sibling denial, attributed pickup/undo, archive, stale/null guards, direct write denial, foreign/no-identity denial, history and ACLs';
END $test$;
ROLLBACK;
